function promoFor(code){return db.promos.filter(x=>x.active&&x.code===code&&new Date(x.until+'T23:59:59')>=TODAY).sort((a,b)=>b.percent-a.percent)[0];}
function price(code,qty=1){const p=product(code);if(!p)return 0;const promo=promoFor(code);return Math.round(p.base*(1-(promo?.percent||0)/100)*multiplier(qty));}
function reserved(code){return db.orders.filter(o=>o.kind==='b2b'&&o.status==='preparando').reduce((s,o)=>s+o.lines.filter(l=>l.code===code).reduce((a,l)=>a+l.qty,0),0);}
function available(code){const p=product(code);return p?.stock==null?null:Math.max(0,p.stock-reserved(code));}
function unavailable(p){return p.active===false||p.stock===0||(p.stock==null&&p.sourceUnavailable);}
function retailReserved(id,code){return db.orders.filter(o=>o.kind==='retail'&&o.client===id&&['recibido','preparando','listo'].includes(o.status)).reduce((a,o)=>a+o.lines.filter(l=>l.code===code).reduce((b,l)=>b+l.qty,0),0);}
function retailAvailable(id,code){return Math.max(0,(db.retail[id]?.[code]?.qty||0)-retailReserved(id,code));}
function retailTotal(){const c=db.retailCart;return c.items.reduce((s,i)=>s+i.qty*(db.retail[c.client]?.[i.code]?.price||0),0);}
function cartLines(){return db.cart.items.map(i=>{const p=product(i.code);return p?{code:i.code,title:p.title,qty:i.qty,base:p.base,unit:price(i.code,i.qty)}:null;}).filter(Boolean);}
function cartTotals(){const subtotal=cartLines().reduce((s,l)=>s+l.qty*l.unit,0),budget=Math.round(subtotal*.08),discount=Math.min(Math.round(subtotal*db.cart.discount/100),budget);return{subtotal,discount,total:subtotal-discount,commission:budget-discount};}
