  db.retail[o.client]??={};o.lines.forEach(l=>{const prev=db.retail[o.client][l.code]||{qty:0,price:0,published:false};db.retail[o.client][l.code]={...prev,qty:prev.qty+l.qty,cost:l.unit};});customer(o.client).last=iso(new Date());
